  checkGameState();
  if (gameState != GameState.GAME_OVER) {
    turn = (turn == 1) ? 2 : 1;
    gameState = (gameState == GameState.PLAYER_TURN) ? GameState.AI_TURN : GameState.PLAYER_TURN;
  }
}

void turns() {
  checkGameState();
  if (gameState == GameState.PLAYER_TURN) {
    if (placedallships==true) {
      gameState = GameState.AI_TURN;
    }
  }
  if (gameState == GameState.AI_TURN) {
    myPlayer2.shoot();
  }
}

