  if (gameState == GameState.GAME_OVER && key == 'r') {
    setup();
  }
  if (gameState == GameState.PLAYER_TURN) {
    turns();
  }
  if (gameState == GameState.AI_TURN) {
    turns();
  }
  if (key == 'p' && keyPressed) {
    printt();
  }
}



void mousePressed() {
  if (mouseButton == LEFT && turn==1 && placedallships == false) {
    for (int r=0; r<20; r++) {
      for (int c=0; c<20; c++) {
        if (mouseX>b[r] && mouseX<b[r+1] && mouseY>b[c] && mouseY<b[c+1] && ships1<10 && grid[r][c]!=1 && grid[r][c]!=2) {
          fill(50, 50, 100);
          ships1++;
          square(b[r], b[c], 25);
          grid[r][c]=1;
          if (ships1==10) {
            placedallships = true;
          }
        }
      }
    }
  }
  if (mouseButton == RIGHT && gameState == GameState.PLAYER_TURN) {
    for (int r=0; r<20; r++) {
      for (int c=0; c<20; c++) {
        checkGuess(r, c);
      }
    }
  }
}

void checkGuess(int r, int c) {
  if (mouseX>b[r] && mouseX<b[r+1] && mouseY>b[c] && mouseY<b[c+1] && ships1<10 && grid[r][c]==-1) {
    if (grid[r][c] == -1) { // Hit
      println("Hit at " + r + ", " + c);
      grid[r][c] = -2; //Player's 2 ship is shot
      fill(250, 70, 50);
      square(b[r], b[c], 15);
    } else if (grid[r][c] == 0) { // Miss
      println("Miss at " + r + ", " + c);
      grid[r][c] = 3; // Miss
      fill(250, 170, 150);
      square(b[r], b[c], 15);
      gameState = GameState.AI_TURN;
    }
  }
}

void grabshots() {
  for (int r=0; r<20; r++) {
    for (int c=0; c<20; c++) {
      if (grid[r][c]==2) {
        fill(200, 0, 0);
        square(b[r]+7.5, b[c]+7.5, 10);
        fill(100);
      }
    }
  }
}

void drawgrid() {
  for (int r=0; r<500; r+=25) {
    for (int c=0; c<500; c+=25) {
      fill(100);
      square(r, c, 25);
    }
  }
  fill(25);
}

void printt() {
  println();
  print("player"+ turn + " board");
  println();
  for (int r=0; r<20; r++) {
    for (int c=0; c<20; c++) {
      print(grid[c][r] + ", ");
    }
    println();
  }
}
